#include <stdio.h>

int main(void) {
    int a[] = {2, 1, 5, 3, 4};
    int n = 5, stk[5], top = 0, nge[5];
    for (int i = 0; i < n; i++) nge[i] = -1;
    for (int i = 0; i < n; i++) {
        /* 栈顶元素比当前小 -> 当前就是它的下一个更大元素，批量结算 */
        while (top > 0 && a[stk[top - 1]] < a[i]) nge[stk[--top]] = a[i];
        stk[top++] = i;                      /* 存下标，便于写回答案 */
    }
    printf("数组:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n每个元素的下一个更大元素:\n");
    for (int i = 0; i < n; i++)
        printf("  a[%d]=%d -> %d\n", i, a[i], nge[i]);
    return 0;
}
